574:       Math.cos(a0) * r0, y0, Math.sin(a0) * r0,
575:       Math.cos(a0) * r1, y1, Math.sin(a0) * r1
576:     );
577:   }
578: }
579: for (let r = 1; r <= netRings; r++) {
580:   const t = r / (netRings + 1);
581:   const rad = topR + (botR - topR) * t;
582:   const y = -0.02 - t * 0.46;
