999: function nearestDefender(actor = activeActor()) {
1000:   let best = null, bd = Infinity;
1001:   for (const d of awayTeam.actors) {
1002:     const dist = Math.hypot(actor.x - d.x, actor.z - d.z);
1003:     if (dist < bd) { bd = dist; best = d; }
