1008: function contestAmount(actor = activeActor()) {
1009:   const { defender, dist } = nearestDefender(actor);
1010:   if (!defender) return 0;
1011:   let c = Math.max(0, Math.min(1, 1 - (dist - 0.6) / 1.6));
1012:   const hx = HOOP.x - actor.x, hz = HOOP.z - actor.z;
1013:   const dx = defender.x - actor.x, dz = defender.z - actor.z;
1014:   const hl = Math.hypot(hx, hz) || 1, dl = Math.hypot(dx, dz) || 1;
1015:   const alignment = (hx * dx + hz * dz) / (hl * dl);
1016:   c *= Math.max(0, Math.min(1, (alignment + 0.3) / 1.1));
1017:   if (defender.screened > 0 || defender.screenHold > 0) c *= 0.35;
1018:   if (state.stepbackTimer > 0) c *= 0.5;
1019:   return c;
1020: }
