<style>
:root{color-scheme:dark;--lime:#d8ff3e;--cream:#f4f1e8;--coral:#ff7a5f;--ink:#071313}
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#071313;color:var(--cream);font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif;touch-action:none}
body{background:radial-gradient(ellipse at 50% 45%,#20352f 0%,#0b1c1b 65%,#071313 100%)}
button{font:inherit;color:inherit;cursor:pointer}
#game{position:relative;width:100%;height:100%;min-height:100dvh;overflow:hidden}
canvas{position:absolute;inset:0;width:100%;height:100%;display:block}
.grain{position:absolute;inset:0;pointer-events:none;z-index:2;opacity:.09;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E")}
.topbar{position:absolute;z-index:3;top:0;left:0;right:0;padding:24px clamp(18px,4vw,56px);display:flex;align-items:flex-start;justify-content:space-between;pointer-events:none}
.brand{display:flex;align-items:center;gap:12px;font-size:12px;font-weight:900;letter-spacing:.18em}
.brandmark{width:32px;height:32px;border:1px solid #d8ff3e;border-radius:50%;display:grid;place-items:center;color:var(--lime);font-size:14px}
.brand small{display:block;color:#9eaaa0;font-size:9px;letter-spacing:.24em;margin-top:3px}
.live{display:flex;align-items:center;gap:7px;color:#d9e2d9;font-size:10px;font-weight:800;letter-spacing:.2em}
.live i{display:block;width:6px;height:6px;border-radius:50%;background:#c9ff37;box-shadow:0 0 12px #c9ff37}
.scoreboard{position:absolute;z-index:4;top:22px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:22px;padding:12px 21px;border:1px solid #ffffff2e;background:linear-gradient(180deg,#081413fa,#081413f0);border-radius:8px;box-shadow:0 12px 44px #0008,0 0 0 1px #0006 inset;pointer-events:none}
.team{text-align:center;min-width:52px}
.team label{display:block;color:#94a39a;font-size:8px;letter-spacing:.2em;font-weight:800}
.team strong{display:block;font-size:23px;line-height:1.1;letter-spacing:-.04em;transition:.15s}
.team.home strong{color:var(--lime)}
.team strong.pop{transform:scale(1.35);color:#fff}
.clock{min-width:62px;text-align:center;border-left:1px solid #ffffff22;border-right:1px solid #ffffff22;padding:0 14px}
.clock strong{font-variant-numeric:tabular-nums;font-size:20px;letter-spacing:.03em}
.clock small{display:block;color:#9aa99f;font-size:8px;letter-spacing:.18em;margin-top:2px;white-space:nowrap}
.statbox{position:absolute;top:104px;left:clamp(18px,4vw,56px);z-index:3;display:flex;gap:8px;pointer-events:none;transition:opacity .3s}
.stat{padding:9px 13px;border:1px solid #ffffff20;background:#091918c9;border-radius:5px;min-width:71px}
.stat span{display:block;color:#82948a;font-size:8px;font-weight:800;letter-spacing:.16em}
.stat b{display:block;margin-top:2px;font-size:15px;font-variant-numeric:tabular-nums;white-space:nowrap}
.shotclock{position:absolute;top:105px;right:clamp(18px,4vw,56px);z-index:3;display:flex;align-items:center;gap:10px;color:#a4b1a8;font-size:9px;font-weight:800;letter-spacing:.18em;pointer-events:none;transition:opacity .3s;background:#091918cf;border:1px solid #ffffff1e;border-radius:5px;padding:6px 10px}
.shotclock b{font-size:21px;color:var(--cream);font-variant-numeric:tabular-nums}
.shotclock.hot b{color:#ff735d}
.bottom-hud{position:absolute;z-index:4;bottom:22px;left:clamp(18px,4vw,56px);right:clamp(18px,4vw,56px);display:flex;align-items:flex-end;justify-content:space-between;pointer-events:none;transition:opacity .3s}
.tips{color:#a7b3a9;font-size:10px;line-height:1.8;letter-spacing:.06em;text-shadow:0 2px 6px #000}
.tips b{color:#edf4e9}
.tips .lit{color:var(--lime)}
.pause-pill{position:absolute;z-index:4;top:56px;right:clamp(18px,4vw,56px);border:1px solid #ffffff38;background:#091817b8;border-radius:4px;padding:8px 11px;font-size:9px;font-weight:900;letter-spacing:.16em;pointer-events:auto;visibility:hidden}
#game.active .pause-pill{visibility:visible}
.pause-pill:hover{border-color:var(--lime);color:var(--lime)}
.toast{position:absolute;z-index:5;left:50%;top:25%;transform:translate(-50%,-10px);font-size:clamp(18px,2.8vw,28px);font-weight:950;letter-spacing:.08em;color:var(--lime);text-shadow:0 4px 20px #000;opacity:0;transition:.3s;pointer-events:none;white-space:nowrap}
.toast.show{opacity:1;transform:translate(-50%,0)}
.toast.bad{color:var(--coral)}
.toast small{display:block;text-align:center;font-size:10px;letter-spacing:.2em;color:#d9e5d8;margin-top:4px}
.overlay{position:absolute;z-index:8;inset:0;display:grid;place-items:center;padding:24px;background:linear-gradient(90deg,#071313e8,#0713134d 55%,#0713139e);transition:opacity .35s,visibility .35s}
.overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}
.card{width:min(570px,100%);margin-right:auto;margin-left:clamp(16px,8vw,130px);position:relative}
