.eyebrow:before{content:"";width:23px;height:1px;background:var(--lime)}
h1{font-size:clamp(54px,8.5vw,110px);line-height:.83;letter-spacing:-.085em;margin:19px 0 20px;font-weight:950}
h1 span{display:block;color:var(--lime)}
.deck{max-width:375px;color:#b8c5bb;font-size:14px;line-height:1.65;margin-bottom:28px}
