.play-btn:hover{transform:translateY(-2px);filter:brightness(1.08)}
.play-btn .arrow{font-size:16px;margin-left:20px}
.ghost-btn{border:1px solid #ffffff45;background:#0a1816b8;border-radius:4px;padding:15px 18px;font-size:10px;font-weight:900;letter-spacing:.14em;transition:.15s;color:#dfe8dc;white-space:nowrap}
